def find_path(graph, start, goal):
    # Initialize the queue with a tuple of (current node, path taken so far)
    queue = [(start, [start])]
    # Keep track of the nodes we have already visited to avoid cycles
    visited = set()

    while queue:
        current_node, path = queue.pop(0)
        # If the current node is the goal, return the path
        if current_node == goal:
            return sorted(path, key=lambda x: x.lower())
        # If the current node has not been visited
        if current_node not in visited:
            visited.add(current_node)
            # Add all neighbors to the queue
            for neighbor in sorted(graph.get(current_node, []), key=lambda x: x.lower()):
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
    # If the queue is exhausted and we haven't found the goal return None
    return None
